def __init__(self, *args, **kwargs):
     super().__init__(*args, **kwargs)
     self.torch_random = torch.Generator()
     self.numpy_random = np.random.default_rng()
     if seed is not None:
         self.torch_random.manual_seed(seed)
         self.numpy_random.seed(seed)
     else:
         self.torch_random.manual_seed(torch.initial_seed())
         self.numpy_random.seed(np.random.randint(0, 2**32 - 1))

